// TH15 v1.00b stage 4 midboss wave: st04.ecl.txt MainSub01 917-959.
// ECir01 enemy body: st04.ecl.txt:105-139; laser volley ECir01_at: 141-175.
// Card frame 0 = source line 917. Enemies spawn over 0..120; each enemy's volley
// starts at enemy-local 60 and its source drift (moveVel/moveSpeedTime) at 240.

const TIME_LIMIT: int = 1224;
const OPENING_BUFFER: int = 120;

// F1 = 3.883222 rad per laser = 40503 BAM; Easy subtracts F1 twice (2*F1 mod 65536).
const STEP_F1: int = 40503;
const STEP_EASY: int = 15470;

// laserNew(0, 0, 128, 0, 16): Line judged segment is [0.1L, 0.9L], so the full
// judged length is 0.8*128 = 102.4 and w=16 (<32) gives half-height w/4=4 -> width 8.
const BEAM_LEN: fx = 102.4fx;
const BEAM_WIDTH: fx = 8.0fx;
// Source Line needs L>16 before it has judgment; at speed 0.4 that is frame 40.
const BEAM_WARN: int = 40;
// Backstop only; beams are normally cancelled once fully offscreen (~150 frames).
const BEAM_ACTIVE: int = 200;

// Source ECir01_at: etSpeed 0.4 px/frame, WAIT 60, then ACCEL 0.1 for 120 frames
// (0.4 -> 12.4 px/frame), then constant. F is the far-end travel distance.
sub beam_step(h: int, age: int, ex: fx, ey: fx) {
    if lz_alive(h) == 0 {
        return;
    }
    var a: angle = lz_angle(h);
    var u: int = age - 60;
    var f: fx = 0.0fx;
    if age <= 60 {
        f = 0.4fx * (age as fx);
    } else if u <= 120 {
        var uf: fx = u as fx;
        f = 24.0fx + 0.4fx * uf + 0.05fx * uf * uf;
    } else {
        f = 792.0fx + 12.4fx * ((u - 120) as fx);
    }
    // Near end of the judged segment: 0.1L while growing, then origin travel + 0.1L.
    var near: fx = 0.0fx;
    if f <= 128.0fx {
        near = 0.1fx * f;
    } else {
        near = f - 115.2fx;
    }
    var ca: fx = cos(a);
    var sa: fx = sin(a);
    var tx: fx = 30000.0fx;
    if ca > 0fx {
        tx = (192.0fx - ex) / ca;
    }
    if ca < 0fx {
        tx = (0.0fx - 192.0fx - ex) / ca;
    }
    var ty: fx = 30000.0fx;
    if sa > 0fx {
        ty = (448.0fx - ey) / sa;
    }
    if sa < 0fx {
        ty = (0.0fx - ey) / sa;
    }
    var lim: fx = tx;
    if ty < lim {
        lim = ty;
    }
    if near > lim + 8.0fx {
        lz_cancel(h);
        return;
    }
    lz_origin(h, ex + near * ca, ey + near * sa);
}

