// Source ECir01 body. Birth animation (scale/alpha/movePosRel slide) and drops are
// omitted; the enemy is placed at its final spawn point from frame 0.
async sub ecir_enemy() {
    set_invuln(65535);
    set_hurtbox(12.0fx);   // setHurtbox(24,24): 24*0.5
    set_hitbox(8.0fx);     // setHitbox(16,16): 16*0.5
    wait(60);
    spawn ecir_volley();
    wait(180);
    move_vel(0, aim_player(), 0.0fx, EASE_LINEAR);  // moveVel(ANGLE_PLAYER, 0)
    move_speed(120, 1.0fx, EASE_LINEAR);            // moveSpeedTime(120, 0, 1.0)
    loop {
        wait(1000);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var r: int = global(GVAR_RANK);
    _ = spawn_enemy(0.0fx, 128.0fx, 400, 0, 1000, 1, ecir_enemy);
    if r == RANK_LUNATIC {
        _ = spawn_enemy(128.0fx, 96.0fx, 200, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    if r == RANK_HARD || r == RANK_LUNATIC {
        _ = spawn_enemy(0.0fx, 32.0fx, 400, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    _ = spawn_enemy(32.0fx, 128.0fx, 400, 0, 1000, 1, ecir_enemy);
    if r == RANK_LUNATIC {
        _ = spawn_enemy(-128.0fx, 96.0fx, 200, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    if r == RANK_HARD || r == RANK_LUNATIC {
        _ = spawn_enemy(-96.0fx, 64.0fx, 400, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    _ = spawn_enemy(-64.0fx, 128.0fx, 400, 0, 1000, 1, ecir_enemy);
    if r == RANK_LUNATIC {
        _ = spawn_enemy(128.0fx, 96.0fx, 200, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    if r == RANK_HARD || r == RANK_LUNATIC {
        _ = spawn_enemy(0.0fx, 64.0fx, 400, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    _ = spawn_enemy(64.0fx, 128.0fx, 400, 0, 1000, 1, ecir_enemy);
    if r == RANK_LUNATIC {
        _ = spawn_enemy(-128.0fx, 96.0fx, 200, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    if r == RANK_HARD || r == RANK_LUNATIC {
        _ = spawn_enemy(96.0fx, 64.0fx, 400, 0, 1000, 1, ecir_enemy);
    }
    wait(15);
    _ = spawn_enemy(-32.0fx, 128.0fx, 400, 0, 1000, 1, ecir_enemy);
    if r == RANK_LUNATIC {
        _ = spawn_enemy(0.0fx, 96.0fx, 200, 0, 1000, 1, ecir_enemy);
    }
    wait(140);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop {
        wait(1);
    }
}

sub main() {
    _ = spawn_enemy(0.0fx, 0.0fx, 1000, 0, 0, 0, control);
    loop {
        wait(600);
    }
}
